import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { Separator } from "@/registry/erbium/ui/separator";

export default function SeparatorExample() {
  return (
    <div>
      <div className="space-y-1">
        <h4 className="text-subtitle">Radix Primitives</h4>
        <p className="text-caption text-muted-foreground">An open-source UI component library.</p>
      </div>
      <Separator className="my-4" />
      <div className="flex h-5 items-center space-x-4 text-caption">
        <div>Blog</div>
        <Separator orientation="vertical" />
        <div>Docs</div>
        <Separator orientation="vertical" />
        <div>Source</div>
      </div>
    </div>
  );
}

import { Separator } from "@/registry/erbium/ui/separator";

export default function SeparatorVerticalExample() {
  return (
    <div className="flex h-5 items-center gap-group text-caption">
      <div>Blog</div>
      <Separator orientation="vertical" />
      <div>Docs</div>
      <Separator orientation="vertical" />
      <div>Source</div>
    </div>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Separator } from "@/registry/erbium/ui/separator";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



import OverviewExample from "./variants/overview";



import VerticalExample from "./variants/vertical";



import LabeledExample from "./variants/labeled";



import FullWidthExample from "./variants/full-width";



import OnSurfacesExample from "./variants/on-surfaces";



import MenuExample from "./variants/menu";



import ListExample from "./variants/list";



import MarginSizingExample from "./variants/margin-sizing";



const meta = {
  component: Separator,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Separate content visually or semantically.

**Import:** `@/registry/erbium/ui/separator`

## Usage

```tsx
import { Separator } from "@/registry/erbium/ui/separator";
```

```tsx
<Separator />
```

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Separator](https://base-ui.com/react/components/separator)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Separator>;

export default { ...meta, title: "Components/Separator",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<Parameters<typeof PlaygroundExample>[0]> = {
  argTypes: {
    orientation: { control: "select", options: ["horizontal", "vertical"] },
    variant: { control: "select", options: [undefined, "full", "inset"] },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { Separator } from "@/registry/erbium/ui/separator";
import type * as React from "react";

export const defaultProps = {
  className: "",
  orientation: "horizontal",
} satisfies Omit<React.ComponentProps<typeof Separator>, "className"> & { className?: string };

export default function SeparatorPlaygroundExample(
  args: Omit<React.ComponentProps<typeof Separator>, "className"> & {
    className?: string;
  } = defaultProps,
) {
  return (
    <div className="flex h-28 w-72 flex-col items-center justify-center">
      <Separator
        {...args}
        className={
          args.orientation === "vertical"
            ? `h-full ${args.className ?? ""}`
            : `w-full ${args.className ?? ""}`
        }
      />
    </div>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { Separator } from "@/registry/erbium/ui/separator";

export default function SeparatorExample() {
  return (
    <div>
      <div className="space-y-1">
