export const Labeled: Story = {
  parameters: {
    docs: {
      description: { story: "A centered label stays readable while the carved lines fade at the outer edges." },
      source: { code: "import { Separator } from "@/registry/erbium/ui/separator";

export default function SeparatorLabeledExample() {
  return (
    <div className="w-72 rounded-lg surface-panel p-4">
      <Separator className="text-metadata text-muted-foreground">or</Separator>
    </div>
  );
}
" },
    },
  },
  render: LabeledExample,
};

export const FullWidth: Story = {
  parameters: {
    docs: {
      description: { story: "Without a `variant`, a separator follows its container. On a surface it runs solid to both edges; in padded content (`separator-inset`) and on the canvas it fades. Pass `variant="full"` or `variant="inset"` to choose." },
      source: { code: "import { Separator } from "@/registry/erbium/ui/separator";

export default function SeparatorFullWidthExample() {
  return (
    <div className="grid w-72 gap-section">
      <div className="overflow-hidden rounded-lg surface-panel py-3">
        <div className="px-3 pb-3 text-caption">Card header</div>
        <Separator />
        <div className="separator-inset grid gap-3 p-3 text-caption text-muted-foreground">
          Card content
          <Separator />
          Inset content divider
        </div>
      </div>
      <div className="grid gap-3 text-caption text-muted-foreground">
        Canvas
        <Separator />
        <Separator variant="full" />
      </div>
    </div>
  );
}
" },
    },
  },
  render: FullWidthExample,
};

export const OnSurfaces: Story = {
  parameters: {
    docs: {
      description: { story: "The translucent shadow and catchlight are checked across the surface palette in both themes." },
      source: { code: "import { Separator } from "@/registry/erbium/ui/separator";
import { surfaceSamples } from "../helpers";

export default function SeparatorOnSurfacesExample() {
  return (
    <div className="grid w-160 max-w-[calc(100vw-2rem)] grid-cols-2 gap-3 p-4 sm:grid-cols-3">
      {surfaceSamples.map(([name, surface]) => (
        <div
          key={name}
          className={`flex min-h-24 flex-col justify-center gap-related rounded-lg border border-transparent p-3 ${surface}`}
        >
          <span className="text-metadata font-medium">{name}</span>
          <Separator />
          <Separator className="text-metadata">or</Separator>
        </div>
      ))}
    </div>
  );
}
" },
    },
  },
  render: OnSurfacesExample,
};

export const Menu: Story = {
  parameters: {
    docs: {
      description: { story: "Vertical separators between menu items with descriptions." },
      source: { code: "import { Separator } from "@/registry/erbium/ui/separator";

export default function SeparatorMenuExample() {
  return (
    <div className="flex items-center gap-related text-caption md:gap-group">
      <div className="flex flex-col gap-1">
        <span className="font-medium">Settings</span>
        <span className="text-metadata text-muted-foreground">Manage preferences</span>
      </div>
      <Separator orientation="vertical" />
      <div className="flex flex-col gap-1">
        <span className="font-medium">Account</span>
        <span className="text-metadata text-muted-foreground">Profile & security</span>
      </div>
      <Separator orientation="vertical" className="hidden md:block" />
      <div className="hidden flex-col gap-1 md:flex">
        <span className="font-medium">Help</span>
        <span className="text-metadata text-muted-foreground">Support & docs</span>
      </div>
    </div>
  );
}
" },
    },
  },
  render: MenuExample,
};

export const List: Story = {
  parameters: {
    docs: {
      description: { story: "Horizontal separators between list items." },
      source: { code: "import { SeparatorList } from "../examples/separator-list";

export default function SeparatorListExample() {
  return (
    <div className="w-72 max-w-[calc(100vw-2rem)]">
